
function weddingStory(){return `<section class="page-heading wedding-heading"><a class="text-link" href="${url('/portfolio/')}">← ${t('Tagasi portfooliosse','Back to portfolio')}</a><span class="eyebrow">${t('PULMALUGU','A WEDDING STORY')}</span><h1>Karen <em>&amp;</em> Rauno</h1><p>${t('Koos. Just selles hetkes.','Together. In this moment.')}</p><div class="wedding-facts"><div><span class="eyebrow">${t('AEG','WHEN')}</span><p>${t('Kuupäev ja kellaaeg lisanduvad','Date and time to be added')}</p></div><div><span class="eyebrow">${t('KOHT','WHERE')}</span><p>${t('Peokoha nimi ja asukoht lisanduvad','Venue and location to be added')}</p></div></div></section><section class="wedding-cover"><img src="/wedding.jpg" alt="${t('Pulmapaar hobustega õhtuvalguses','Wedding couple with horses in evening light')}"></section><section class="section wedding-team"><div><span class="eyebrow">${t('SELLE PÄEVA LOOMISE JUURES','BEHIND THE DAY')}</span><h2>${t('Inimesed detailide taga.','The people behind the details.')}</h2><p class="small">${t('Pulmatiimi nimed ja lingid lisanduvad pärast kinnitamist.','Wedding team names and links will be added once confirmed.')}</p></div><dl>${[['Fotograaf','Photography'],['Pulmaisa','Wedding host'],['Videograaf','Videography'],['Pulmade korraldamine ja koordineerimine','Wedding planning and coordination'],['Florist','Florist']].map(([et,en])=>`<div><dt>${t(et,en)}</dt><dd>${t('Lisandub','To be added')}</dd></div>`).join('')}</dl></section><section class="section wedding-gallery-section"><span class="eyebrow">${t('FOTOGALERII','PHOTO GALLERY')}</span><h2>${t('Hetked, mis jäävad.','Moments that stay.')}</h2><p class="small">${t('Esimene foto on galeriis. Ülejäänud üheksa fotot lisanduvad.','The first photograph is in the gallery. Nine more photographs will be added.')}</p><div class="wedding-photo-grid"><button type="button" class="wedding-photo" id="open-wedding-photo" aria-label="${t('Ava foto täissuuruses','View full-size photograph')}"><img src="/wedding.jpg" loading="lazy" alt="${t('Pulmapaar hobustega','Wedding couple with horses')}"><span>01 ↗</span></button>${Array.from({length:9},(_,i)=>`<div class="wedding-photo-placeholder"><span>${String(i+2).padStart(2,'0')}</span><p>${t('Foto lisandub','Photograph coming soon')}</p></div>`).join('')}</div></section><section class="section wedding-testimonial"><span class="eyebrow">${t('PRUUTPAARI SÕNAD','FROM THE COUPLE')}</span><h2>${t('Nende päeva lugu.','Their day, in their words.')}</h2><p>${t('Pruutpaari tagasiside lisandub nende loal.','The couple’s words will be added with their permission.')}</p></section><section class="section portfolio-contact"><h2>${t('Loome teie päeva.','Let’s create your day.')}</h2>${link('/contact/',t('Võta ühendust','Get in touch'))}</section><dialog id="wedding-lightbox" aria-label="${t('Pulmafoto','Wedding photograph')}"><button type="button" id="close-wedding-photo" aria-label="${t('Sulge foto','Close photograph')}">×</button><img src="/wedding.jpg" alt="${t('Pulmapaar hobustega kuldses õhtuvalguses','Wedding couple with horses in golden evening light')}"></dialog>`}
function initWeddingGallery(){const dialog=$('#wedding-lightbox');$('#open-wedding-photo').onclick=()=>dialog.showModal();$('#close-wedding-photo').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()}}

function portfolio(){return `<section class="page-heading"><span class="eyebrow">EHE EVENTS · ${t('PORTFOOLIO','PORTFOLIO')}</span><h1>${t('Ehedad hetked.<br><em>Päris emotsioonid.</em>','Genuine moments.<br><em>Real emotions.</em>')}</h1><p>${t('Hetked, mille juurde tahaks tagasi tulla.','Moments worth returning to.')}</p></section><section class="section portfolio-gallery"><figure><a href="${url('/portfolio/wedding/')}" aria-label="${t('Vaata pulmalugu','View wedding story')}"><img src="/wedding.jpg" alt="${t('Pulmapaar hobustega kuldses õhtuvalguses','Wedding couple with horses in golden evening light')}" loading="lazy"></a><figcaption><a class="portfolio-story-link" href="${url('/portfolio/wedding/')}"><span class="eyebrow">${t('PULMAD','WEDDINGS')} ↗</span><h2>Karen &amp; Rauno</h2><p>${t('Koos. Just selles hetkes.','Together. In this moment.')}</p><span class="text-link">${t('Vaata pulmalugu ja galeriid','Explore the wedding and gallery')}</span></a></figcaption></figure>${Array.from({length:3},(_,i)=>`<figure class="portfolio-placeholder-card"><div class="portfolio-placeholder-image"><span class="placeholder-number">0${i+2}</span><span class="eyebrow">${t('FOTO LISANDUB','PHOTO COMING SOON')}</span></div><figcaption><span class="eyebrow">${t('PULMAD · NÄIDISKOHT','WEDDINGS · PLACEHOLDER')}</span><h2>${t('Pruut & peigmees','Bride & groom')}</h2><p>${t('Siia lisandub järgmise paari pulmalugu.','Another couple’s wedding story will appear here.')}</p><span class="small">${t('Lugu lisandub','Story coming soon')}</span></figcaption></figure>`).join('')}</section><section class="section portfolio-contact"><h2>${t('Milline on teie lugu?','What is your story?')}</h2><p>${t('Loome teie päeva ümber ruumi ehedatele hetkedele.','Let’s make room for genuine moments on your day.')}</p>${link('/contact/',t('Räägime teie päevast','Let’s talk about your day'))}</section>`}
const $=s=>document.querySelector(s),lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'et',t=(a,b)=>lang==='et'?a:b,paths=['/','/services/','/rentals/','/contact/','/portfolio/','/portfolio/wedding/'],page=Math.max(0,paths.indexOf(location.pathname)),url=p=>p+'?lang='+lang,money=n=>new Intl.NumberFormat(lang==='et'?'et-EE':'en-IE',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(n),link=(p,s)=>`<a class="button" href="${url(p)}">${s} ↗</a>`;
const serviceNames=()=>[t('Pulmade korraldamine','Wedding planning'),t('Pulmade koordineerimine','Wedding coordination'),t('Sündmuste korraldamine','Event planning'),t('Sündmuste koordineerimine','Event coordination')];
function home(){document.body.classList.add('photo-home');const style=document.createElement('link');style.rel='stylesheet';style.href='/homepage.css';document.head.append(style);const box=document.createElement('div');box.innerHTML="<section class=\"hero\"><img src=\"/wedding.jpg\" alt=\"Pulmapaar hobustega kuldses õhtuvalguses\" fetchpriority=\"high\"><div class=\"hero-copy\"><div class=\"eyebrow\" data-et=\"PULMAD · SÜNDMUSED · KOOSOLEMINE\" data-en=\"WEDDINGS · EVENTS · TOGETHERNESS\">PULMAD · SÜNDMUSED · KOOSOLEMINE</div><h1>ehe<span>EVENTS</span></h1><p data-et=\"Ehedad hetked. Ehedad emotsioonid.\" data-en=\"Genuine moments. Genuine emotions.\">Ehedad hetked. Ehedad emotsioonid.</p></div><div class=\"hero-bottom\"><a class=\"scroll\" href=\"#about\"><span>↓</span><b data-et=\"MEIE LUGU ALGAB SIIT\" data-en=\"OUR STORY STARTS HERE\">MEIE LUGU ALGAB SIIT</b></a><div data-et=\"TEIE PÄEV. TEIE MOODI.\" data-en=\"YOUR DAY. YOUR WAY.\">TEIE PÄEV. TEIE MOODI.</div></div></section>\n<div class=\"content-layer\"><section class=\"intro\" id=\"about\"><div><span class=\"eyebrow\">EHE EVENTS</span><h2 data-et=\"Toome fookuse tagasi sisule.\" data-en=\"Back to what matters.\">Toome fookuse tagasi sisule.</h2></div><div><p data-et=\"Kaunis sündmus on enamat kui läbimõeldud detailid. See on kohtumine, naer, lähedus ja tunne, mis jääb. Loome ruumi ehedatele hetkedele ja ehedatele emotsioonidele.\" data-en=\"A beautiful event is more than carefully chosen details. It is connection, laughter and a feeling that stays. We make room for genuine moments and genuine emotions.\">Kaunis sündmus on enamat kui läbimõeldud detailid. See on kohtumine, naer, lähedus ja tunne, mis jääb. Loome ruumi ehedatele hetkedele ja ehedatele emotsioonidele.</p><p data-et=\"Meie hoiame korraldust, teie saate olla kohal.\" data-en=\"We take care of the plans so you can be truly present.\">Meie hoiame korraldust, teie saate olla kohal.</p><a class=\"line-link\" data-path=\"contact\" href=\"/contact/\" data-et=\"Räägime teie päevast ↗\" data-en=\"Let’s talk about your day ↗\">Räägime teie päevast ↗</a></div></section>\n<section class=\"services\"><div class=\"services-top\"><h2 data-et=\"Teie hetk. Meie hoole all.\" data-en=\"Your moment. In good hands.\">Teie hetk. Meie hoole all.</h2><span class=\"eyebrow\" data-et=\"IDEEDEST MÄLESTUSTENI\" data-en=\"FROM IDEAS TO MEMORIES\">IDEEDEST MÄLESTUSTENI</span></div><div class=\"cards\"><article class=\"card\"><span class=\"number\">01 /</span><h3 data-et=\"Pulmad\" data-en=\"Weddings\">Pulmad</h3><p data-et=\"Korraldamine ja koordineerimine, et saaksite nautida oma päeva algusest lõpuni.\" data-en=\"Planning and coordination so you can enjoy your day from beginning to end.\">Korraldamine ja koordineerimine, et saaksite nautida oma päeva algusest lõpuni.</p><a class=\"line-link\" data-path=\"services\" href=\"/services/\" data-et=\"Avasta võimalused ↗\" data-en=\"Explore the possibilities ↗\">Avasta võimalused ↗</a></article><article class=\"card\"><span class=\"number\">02 /</span><h3 data-et=\"Sündmused\" data-en=\"Events\">Sündmused</h3><p data-et=\"Isiklikud tähistamised ja ettevõtete sündmused. Iga kohtumine väärib oma nägu.\" data-en=\"Personal celebrations and company events. Every gathering deserves its own character.\">Isiklikud tähistamised ja ettevõtete sündmused. Iga kohtumine väärib oma nägu.</p><a class=\"line-link\" data-path=\"services\" href=\"/services/\" data-et=\"Leiame teie lahenduse ↗\" data-en=\"Find your perfect fit ↗\">Leiame teie lahenduse ↗</a></article><article class=\"card\"><span class=\"number\">03 /</span><h3 data-et=\"Detailide rent\" data-en=\"Finishing touches\">Detailide rent</h3><p data-et=\"Loorid, küünlatopsid ja dekoratsioonid. Väikesed detailid, mis loovad suure tunde.\" data-en=\"Veils, candle holders and decorations. Little details that make a lasting impression.\">Loorid, küünlatopsid ja dekoratsioonid. Väikesed detailid, mis loovad suure tunde.</p><a class=\"line-link\" data-path=\"rentals\" href=\"/rentals/\" data-et=\"Vaata kollektsiooni ↗\" data-en=\"View the collection ↗\">Vaata kollektsiooni ↗</a></article></div></section><section class=\"closing\"><span class=\"eyebrow\" data-et=\"KÕIK ALGAB ÜHEST MÕTTEST\" data-en=\"IT ALL BEGINS WITH AN IDEA\">KÕIK ALGAB ÜHEST MÕTTEST</span><h2 data-et=\"Loome midagi ehedat.\" data-en=\"Let’s create something genuine.\">Loome midagi ehedat.</h2><a href=\"mailto:karen@eheevents.ee\">karen@eheevents.ee ↗</a></section></div>";box.querySelectorAll('[data-et]').forEach(n=>n.textContent=n.dataset[lang]);box.querySelectorAll('[data-path]').forEach(n=>n.href=url('/'+n.dataset.path+'/'));return box.innerHTML}
function services(){return `<section class="page-heading"><span class="eyebrow">${t('TEENUSED','OUR SERVICES')}</span><h1>${t('Teie hetk.<br>Meie <em>hoole all.</em>','Your moment.<br>In <em>good hands.</em>')}</h1><p>${t('Tugi algusest peale või kindel käsi sündmuse päeval. Valige just teile sobiv abi.','Support from the very beginning or a steady hand on the day. Choose what feels right for you.')}</p><a class="text-link" href="#calculator">${t('Sündmuse hinnakalkulaator','Event price calculator')} ↓</a></section><section class="section"><div class="services">${serviceNames().map((s,i)=>`<article class="service"><span class="eyebrow">0${i+1}</span><h3>${s}</h3><p>${[t('Teie visioonist tervikliku pulmapäevani. Kontseptsioon, eelarve, peokoha ja partnerite valik ning ettevalmistuste juhtimine.','From your vision to a complete wedding day. Concept, budget, venue and supplier selection, and preparation management.'),t('Teie olete plaani loonud. Meie jälgime ajakava, juhendame partnereid ja abistame külalisi pulmapäeval.','You have made the plans. We manage the timeline, coordinate suppliers and help your guests on the wedding day.'),t('Juubelid, peod ja ettevõtete sündmused — ideest partnerite, logistika ja läbimõeldud eelarveni.','Anniversaries, parties and company events — from the idea to suppliers, logistics and a considered budget.'),t('Hoiame päevakava ja kohapealsed detailid kontrolli all, kui teie kohtute oma külalistega.','We manage the schedule and on-site details while you spend time with your guests.')][i]}</p><p class="small">${i===0?t('Pool päeva 1080 € · terve päev 2000 €','Half day €1,080 · full day €2,000'):i===1?t('Kuni 14 tundi koordineerimist · 760 €','Up to 14 hours of coordination · €760'):t('Hind personaalse pakkumise alusel','Price by personal quote')}</p></article>`).join('')}</div></section>${calculatorMarkup()}`}
const rentalNames=()=>[t('Pruudiloorid','Bridal veils'),t('Küünlapurgid','Candle jars'),t('Lauavaasid','Table vases')];
function contact(){return `<section class="page-heading"><span class="eyebrow">${t('KONTAKT','GET IN TOUCH')}</span><h1>${t('Kõik algab<br><em>ühest mõttest.</em>','It all begins<br><em>with an idea.</em>')}</h1></section><section class="section contact-grid"><div><h3>${t('Rääkige oma päevast.','Tell us about your day.')}</h3><p>${t('Pulm, tähistamine või kaunid detailid — pange oma soovid kirja.','A wedding, a celebration or beautiful details — put your wishes into words.')}</p><span class="eyebrow">EHE EVENTS · ${t('EESTI','ESTONIA')}</span><div class="notice small">${t('Kirjutage meile: <a href="mailto:karen@eheevents.ee">karen@eheevents.ee</a>. Vorm avab teie e-posti rakenduses kirja mustandi.','Email us: <a href="mailto:karen@eheevents.ee">karen@eheevents.ee</a>. This form opens a draft in your email app.')}</div></div><form id="contact-form" class="contact-form"><label>${t('Teie nimi','Your name')}<input name="name" required autocomplete="name"></label><label>${t('E-post','Email')}<input name="email" required type="email" autocomplete="email"></label><label>${t('Kuupäev (soovi korral)','Date (optional)')}<input name="date" type="date"></label><label>${t('Teie soovid','Your wishes')}<textarea id="message" name="message" required></textarea></label><button class="button" type="submit">${t('Ava e-kirja mustand','Open email draft')} ↗</button><p id="status" class="small" role="status"></p></form></section>`}
(async function(){
await loadSiteSettings();
document.documentElement.lang=lang;document.title=t('EHE Events — Pulmad, sündmused ja rent','EHE Events — Weddings, events & rentals');$('#nav').innerHTML=paths.slice(0,5).map((p,i)=>`<a ${(page===i||(page===5&&i===4))?'class="active" aria-current="page"':''} href="${url(p)}">${[t('Avaleht','Home'),t('Teenused','Services'),t('Rent','Rentals'),t('Kontakt','Contact'),t('Portfoolio','Portfolio')][i]}</a>`).join('');$('#main').innerHTML=[home,services,rentals,contact,portfolio,weddingStory][page]();$('#footertext').textContent=t('Ehedad hetked. Ehedad emotsioonid. EHE Events.','Genuine moments. Genuine emotions. EHE Events.');document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.onclick=()=>{const p=new URL(location.href);p.searchParams.set('lang',b.dataset.lang);location.href=p.href}});
document.querySelectorAll('.brand').forEach(a=>a.href=url('/'));$('#nav').setAttribute('aria-label',t('Peamenüü','Main navigation'));
if(page===1)initCalculator();
if(page===2)initRentals();
if(page===3){let q;try{q=JSON.parse(sessionStorage.getItem('eheQuote'))}catch{}let item=new URLSearchParams(location.search).get('item');if(['0','1','2'].includes(item))$('#message').value=t('Soovin rentida: ','I would like to rent: ')+rentalNames()[+item];else if(q?.version===3){$('#message').value=eventInquiry(q)};$('#contact-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),body=[f.get('name'),f.get('email'),f.get('date'),f.get('message')].join('\n');location.href='mailto:karen@eheevents.ee?subject='+encodeURIComponent(t('Päring EHE Eventsile','EHE Events inquiry'))+'&body='+encodeURIComponent(body);$('#status').textContent=t('E-kirja mustand on avatud. Saatmiseks kinnitage kiri oma e-posti rakenduses. Kui rakendus ei avane, kirjutage aadressile karen@eheevents.ee.','Your email draft has been opened. Send it from your email app. If no app opens, email karen@eheevents.ee directly.')}}

applySiteContent();
if(page===5)initWeddingGallery();
window.eheReady=true;
if(page===3){const date=new URLSearchParams(location.search).get("date");if(/^\d{4}-\d{2}-\d{2}$/.test(date))document.querySelector("[name=date]").value=date}
})();
